import flask
from flask import request, jsonify, g
import sqlite3
import os
import hashlib
import hmac
import time

app = flask.Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/data/users.db')
SECRET = os.environ.get('APP_SECRET', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT UNIQUE, password_hash TEXT, role TEXT DEFAULT "user", email TEXT)')
    db.execute('CREATE TABLE IF NOT EXISTS audit_log (id INTEGER PRIMARY KEY, action TEXT, ts REAL)')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')

    # Validate field name to prevent injection via column names
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    # Build query - value is user-controlled
    query = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        return jsonify([dict(r) for r in results])
    except Exception as e:
        app.logger.error(f"Search error: {e}")
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    db = get_db()
    user = db.execute('SELECT id, username, email, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    pw_hash = hashlib.sha256(data['password'].encode()).hexdigest()
    db = get_db()
    try:
        db.execute('INSERT INTO users (username, password_hash, email) VALUES (?, ?, ?)',
                   (data['username'], pw_hash, data.get('email', '')))
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username exists'}), 409

@app.route('/api/admin/export', methods=['GET'])
def export_data():
    """Export all user data for backup. Requires admin token."""
    token = request.headers.get('X-Admin-Token', '')
    expected = hmac.new(SECRET.encode(), b'admin-export', hashlib.sha256).hexdigest() if hasattr(hmac, 'new') else hmac.HMAC(SECRET.encode(), b'admin-export', hashlib.sha256).hexdigest()
    if not hmac.compare_digest(token, expected):
        return jsonify({'error': 'Unauthorized'}), 403

    db = get_db()
    users = db.execute('SELECT id, username, email, role, password_hash FROM users').fetchall()
    return jsonify([dict(u) for u in users])

@app.route('/health', methods=['GET'])
def health():
    return jsonify({
        'status': 'ok',
        'db': DATABASE,
        'pid': os.getpid(),
        'uptime': time.time()
    })

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', 8080)), debug=False)
